mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.PLAN_ID,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.TARGET_ID,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.WAVE_ID = #{waveId}
AND T1.WAVE_ID IS NULL
AND T1.TARGET_TYPE_CD = #{targetTypeCd}
AND T1.TARGET_ID = #{targetId}
AND T1.STRATEGY_7R_CD = #{strategy7rCd}
AND T1.STATUS_CD = #{statusCd}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.PLAN_ID AS PLAN_ID, T1.WAVE_ID AS WAVE_ID, T1.TARGET_TYPE_CD AS TARGET_TYPE_CD,
           T1.TARGET_ID AS TARGET_ID, T1.STRATEGY_7R_CD AS STRATEGY_7R_CD,
           T1.CURRENT_PLATFORM_CD AS CURRENT_PLATFORM_CD, T1.TARGET_PLATFORM_CD AS TARGET_PLATFORM_CD,
           T1.DIFFICULTY_CD AS DIFFICULTY_CD, T1.STATUS_CD AS STATUS_CD, T1.REMARK AS REMARK
      FROM TB_IF_MIGRATION_PLAN_PILOT T1

     ORDER BY NVL(T1.WAVE_ID,'ZZZ'), T1.PLAN_ID
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

mapper.insert:
INSERT INTO TB_IF_MIGRATION_PLAN_PILOT (
  PLAN_ID, WAVE_ID, TARGET_TYPE_CD, TARGET_ID, STRATEGY_7R_CD,
  CURRENT_PLATFORM_CD, TARGET_PLATFORM_CD, DIFFICULTY_CD, STATUS_CD, REMARK, REG_USER_ID, REG_DTM
) VALUES (
  #{planId}, #{waveId}, #{targetTypeCd}, #{targetId}, #{strategy7rCd},
  #{currentPlatformCd}, #{targetPlatformCd}, #{difficultyCd}, #{statusCd}, #{remark}, #{regUserId}, #{regDtm}
)

mapper.update:
UPDATE TB_IF_MIGRATION_PLAN_PILOT
   SET WAVE_ID=#{waveId}, TARGET_TYPE_CD=#{targetTypeCd}, TARGET_ID=#{targetId},
       STRATEGY_7R_CD=#{strategy7rCd}, CURRENT_PLATFORM_CD=#{currentPlatformCd},
       TARGET_PLATFORM_CD=#{targetPlatformCd}, DIFFICULTY_CD=#{difficultyCd},
       STATUS_CD=#{statusCd}, REMARK=#{remark}, CHG_USER_ID=#{chgUserId}, CHG_DTM=#{chgDtm}
 WHERE PLAN_ID=#{planId}

mapper.delete:
DELETE FROM TB_IF_MIGRATION_PLAN_PILOT
 WHERE PLAN_ID IN
#{id}
